'use strict'
const fs=require('node:fs')
const assert=require('node:assert/strict')
const ui=fs.readFileSync('components/clientes/VendaTipologiasMateriais.tsx','utf8')
const edicao=fs.readFileSync('app/api/vendas/tipologias-materiais/route.ts','utf8')
const validacao=fs.readFileSync('app/api/vendas/wvetro/conferencia-documental/route.ts','utf8')
function verificar(exp,descricao){assert.match(ui,exp,descricao)}
verificar(/onClick=\{iniciarSubstituicao\}[\s\S]{0,250}Substituir \/ Corrigir/, 'Botão de substituição deve iniciar a edição, não só trocar aba')
verificar(/function iniciarSubstituicao\(\)[\s\S]*?perfisAtuais\.length===1[\s\S]*?abrirEdicao\('substituir',perfisAtuais\[0\]\)[\s\S]*?setSelecionandoPerfil\(true\)/, 'Com um perfil abre editor; com vários abre seleção')
verificar(/Selecionar perfil para substituir[\s\S]*?perfisAtuais\.map\(m=>[\s\S]*?abrirEdicao\('substituir',m\)[\s\S]*?fotoMaterial\(m\)/, 'Seleção mostra imagem e abre o perfil escolhido')
verificar(/Material original:[\s\S]*?materialEditando\.descricao/, 'Editor mantém identificação do perfil original')
verificar(/produtoEscolhido&&[\s\S]*?produtoEscolhido\.foto_url[\s\S]*?Produto substituto selecionado/, 'Substituto selecionado exibe imagem')
verificar(/onChange=\{e=>\{setBusca\(e\.target\.value\);setProdutoEscolhido\(null\);setForm\(prev=>\(\{\.\.\.prev,produto_id:'',codigo:''\}\)\)\}\}/, 'Nova pesquisa limpa vínculo anterior')
verificar(/function motivoBloqueioAprovacao\(\):string\|null[\s\S]*?statusAtual==='validada'/, 'Aprovação fornece motivos de bloqueio e status já validado')
verificar(/function solicitarAprovacao\(\)[\s\S]*?if\(motivo\)\{if\(statusAtual==='validada'\)setMensagem\(motivo\);else setErro\(motivo\);return\}[\s\S]*?void confirmarComposicao\(\)/, 'Aprovar executa a rotina quando permitido')
verificar(/disabled=\{salvando\} onClick=\{solicitarAprovacao\}/, 'Botão mostra bloqueios em vez de ficar inerte')
verificar(/form\.append\('acao','validar_atlas'\)/, 'Aprovação usa a ação existente')
assert.match(edicao,/if\(u\.role!=='master'\)/, 'Edição continua restrita a Master no servidor')
assert.match(edicao,/fn_venda_tipologia_material_editar_v1/, 'Substituição mantém chamada transacional')
assert.match(validacao,/if\(c\.u\.role!=='master'\)/, 'Aprovação continua restrita a Master no servidor')
assert.match(validacao,/assinaturaTecnica/, 'Aprovação verifica assinatura técnica vigente')
console.log('PASS: substituir/corrigir e confirmar/aprovar acionáveis; perfil e substituto com imagens; histórico e restrições preservados.')
